<script setup lang="ts">
import {ref,watch,onUnmounted,useId} from 'vue'
import {suggestions,type Suggestion} from '../search/suggestions'
const props=defineProps<{modelValue:string;label:string;placeholder?:string}>(),emit=defineEmits<{'update:modelValue':[string];select:[Suggestion]}>()
const id=useId(),rows=ref<Suggestion[]>([]),open=ref(false),active=ref(-1),message=ref(''),loading=ref(false),composing=ref(false)
let timer:ReturnType<typeof setTimeout>|undefined,ctl:AbortController|null=null,version=0
function stop(){clearTimeout(timer);ctl?.abort();version++;loading.value=false}
function changed(){stop();rows.value=[];active.value=-1;message.value='';const q=props.modelValue.trim();if(composing.value||!q||q.length>80)return;const epoch=version;timer=setTimeout(async()=>{const request=new AbortController();ctl=request;loading.value=true;try{const data=await suggestions(q,request.signal);if(epoch!==version)return;rows.value=data;open.value=true;message.value=data.length?'仅列出公开目录中已存在的名称':'暂无名称联想，可继续输入或直接搜索。'}catch(e){if(!request.signal.aborted&&epoch===version){message.value=(e as Error).message;open.value=true}}finally{if(epoch===version)loading.value=false}},280)}
watch(()=>props.modelValue,changed)
function choose(row:Suggestion){stop();open.value=false;emit('update:modelValue',row.matchedName);emit('select',row)}
function key(e:KeyboardEvent){if(composing.value||e.isComposing){if(e.key==='Enter')e.preventDefault();return;}if(e.key==='Escape'){e.preventDefault();open.value=false;return}if(!open.value||!rows.value.length)return;if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();active.value=(active.value+(e.key==='ArrowDown'?1:-1)+rows.value.length)%rows.value.length}else if(e.key==='Enter'&&active.value>=0){e.preventDefault();choose(rows.value[active.value]!)}}
onUnmounted(stop)
</script>
<template><div class="plant-search-input"><input :id="id" :value="modelValue" :aria-label="label" :placeholder="placeholder" maxlength="80" role="combobox" aria-autocomplete="list" :aria-expanded="open&&Boolean(rows.length)" :aria-controls="id+'-list'" :aria-activedescendant="active>=0?id+'-option-'+active:undefined" autocomplete="off" @input="emit('update:modelValue',($event.target as HTMLInputElement).value)" @keydown="key" @compositionstart="composing=true;stop()" @compositionend="composing=false;changed()" @focus="open=true" @blur="open=false;stop()"/><div v-if="open&&(loading||rows.length||message)" class="plant-search-suggestions"><ul :id="id+'-list'" role="listbox" :aria-label="label+'联想'"><li v-for="(row,index) in rows" :id="id+'-option-'+index" :key="row.id+':'+row.matchedName" role="option" :aria-selected="active===index" @pointerdown.prevent="choose(row)"><b>{{row.matchedName}}</b><small>{{row.label}}<span v-if="row.scientificName&&row.scientificName!==row.matchedName"> · {{row.scientificName}}</span></small><em>{{row.matchType==='SCIENTIFIC_NAME'?'学名匹配':'来源名称匹配'}}</em></li></ul><p role="status">{{loading?'正在查找已有名称…':message}}</p></div></div></template>
<style>
.plant-search-input{position:relative;flex:1;min-width:0;text-align:left}.plant-search-input>input{width:100%;box-sizing:border-box}.plant-search-suggestions{position:absolute;top:100%;left:0;right:0;z-index:30;background:#fffdf7;color:#244632;border:1px solid #d9e3d2;border-radius:12px;box-shadow:0 12px 30px #173b241a;max-height:340px;overflow:auto;min-width:min(280px,80vw)}.plant-search-suggestions ul{padding:5px;margin:0;list-style:none}.plant-search-suggestions li{padding:10px 13px;border-radius:7px;cursor:pointer;line-height:1.7;overflow-wrap:anywhere}.plant-search-suggestions li:hover,.plant-search-suggestions li[aria-selected=true]{background:#eaf0e3}.plant-search-suggestions b,.plant-search-suggestions small{display:block}.plant-search-suggestions small{color:#6e7e68;font-size:11px}.plant-search-suggestions em{font-size:10px;font-style:normal;color:#7b8d72}.plant-search-suggestions p{margin:0!important;padding:9px 15px!important;font-size:11px!important;color:#74846b!important;line-height:1.7}.command-dialog .plant-search-suggestions{position:relative;margin-top:8px}.command-dialog form{align-items:flex-start}.museum-invitation form{overflow:visible!important}
</style>
